Node* closest_node = nullptr;
float min_distance = std::numeric_limits<float>::max();

for (auto& node : m_nodes) {
    bool is_footway_only = true;

    auto it = node_to_road.find(node.index_);
    if (it != node_to_road.end()) {
        for (const Model::Road* road : it->second) {
            if (road->type != Model::Road::Type::Footway) {
                is_footway_only = false;
                break;
            }
        }
    }

    if (!is_footway_only) {
        float dx = node.x - x;
        float dy = node.y - y;
        float distance = std::sqrt(dx * dx + dy * dy);

        if (distance < min_distance) {
            min_distance = distance;
            closest_node = &node;
        }
    }
}

return *closest_node;

